(6498288, 965335, 119667, '<td valign="top">great detail!</td>', 'great detail!', '2011-08-08 15:45:53.000000', NULL, 1),
(6498300, 966154, 135204, '<td valign="top">Too over processed for my taste.</td>', 'Too over processed for my taste.', '2011-08-08 15:53:12.000000', NULL, 1),
(6498305, 966225, 135204, '<td valign="top">Interesting subject, this looks like is was a very nice house at one point.  Unfortunetly I find the photo too over processed.</td>', 'Interesting subject, this looks like is was a very nice house at one point.  Unfortunetly I find the photo too over processed.', '2011-08-08 15:56:07.000000', NULL, 1),
(6498307, 965567, 135204, '<td valign="top">Very nice use of the water to get the reflection.</td>', 'Very nice use of the water to get the reflection.', '2011-08-08 15:57:21.000000', NULL, 1),
(6498311, 965809, 135204, '<td valign="top">Wow, this building looks amazing, I can''t believe it is in such disrepair?  Great working getting the feel of the size and decay.</td>', 'Wow, this building looks amazing, I can''t believe it is in such disrepair?  Great working getting the feel of the size and decay.', '2011-08-08 15:58:50.000000', NULL, 1),
(6498320, 966158, 135204, '<td valign="top">The wild flowers give this a nice splash of colour.  Love your composition and the amount of detail.  Looks like it would make a great print.</td>', 'The wild flowers give this a nice splash of colour.  Love your composition and the amount of detail.  Looks like it would make a great print.', '2011-08-08 16:08:23.000000', NULL, 1),
(6498326, 966229, 135204, '<td valign="top">Nice use of lines.</td>', 'Nice use of lines.', '2011-08-08 16:20:55.000000', NULL, 1),
(6498328, 966124, 109363, '<td valign="top">i thought about a shot like this, but yours is much better</td>', 'i thought about a shot like this, but yours is much better', '2011-08-08 16:21:58.000000', NULL, 1),
(6498329, 966237, 135204, '<td valign="top">Looks haunted :)</td>', 'Looks haunted :)', '2011-08-08 16:22:14.000000', NULL, 1),
