(6498334, 965789, 109363, '<td valign="top">where be the pigs on the wing, mate?</td>', 'where be the pigs on the wing, mate?', '2011-08-08 16:25:46.000000', NULL, 1),
(6498336, 966027, 109363, '<td valign="top">ha ha ... awww....</td>', 'ha ha ... awww....', '2011-08-08 16:26:46.000000', NULL, 1),
