(6502302, 966125, 103032, '<td valign="top">Postcard quality for the area.  Nice tones.</td>', 'Postcard quality for the area.  Nice tones.', '2011-08-12 02:19:07.000000', NULL, 1),
(6502307, 966197, 103032, '<td valign="top">I like the composition in this one, letting the light sneak in through the cracked open door to give the viewer just enough light to peek around the abandoned room/building.  Nice job.</td>', 'I like the composition in this one, letting the light sneak in through the cracked open door to give the viewer just enough light to peek around the abandoned room/building.  Nice job.', '2011-08-12 02:29:11.000000', NULL, 1),
