(6503688, 966108, 113156, '<td valign="top">One of mt top pics for this challenge, love the scale this gives and the rich colors.</td>', 'One of mt top pics for this challenge, love the scale this gives and the rich colors.', '2011-08-14 00:41:37.000000', NULL, 1),
(6503689, 965937, 22970, '<td valign="top">Nice texture and lighting. I like the low point of view but wish I could have seen a wall or two showing the structure of a building. Nice processing.</td>', 'Nice texture and lighting. I like the low point of view but wish I could have seen a wall or two showing the structure of a building. Nice processing.', '2011-08-14 00:45:21.000000', NULL, 1),
(6503694, 965768, 22970, '<td valign="top">Nice texture, color, and felling of abandonment. You subject takes up the majority of your canvas with a great background. Nicely composed and well done.</td>', 'Nice texture, color, and felling of abandonment. You subject takes up the majority of your canvas with a great background. Nicely composed and well done.', '2011-08-14 00:54:01.000000', NULL, 1),
(6503695, 966094, 22970, '<td valign="top">The dramatic sky is nice and a plus to your photograph. However, I do think the shot is taken from to long of a distance to give me a feeling of abandon. I find the foreground catching my eye and then looking up at the sky. It would have been nice if you could have gotten closeup and taken a low point of view shot that included the building and sky. Try to keep your subject on the rule of thirds as well. Hope this helps.</td>', 'The dramatic sky is nice and a plus to your photograph. However, I do think the shot is taken from to long of a distance to give me a feeling of abandon. I find the foreground catching my eye and then looking up at the sky. It would have been nice if you could have gotten closeup and taken a low point of view shot that included the building and sky. Try to keep your subject on the rule of thirds as well. Hope this helps.', '2011-08-14 00:54:03.000000', NULL, 1),
(6503736, 965767, 123833, '<td valign="top">Slightly overdone, looks almost like 3D graphics, nice composition</td>', 'Slightly overdone, looks almost like 3D graphics, nice composition', '2011-08-14 02:06:46.000000', NULL, 1),
(6503831, 965429, 64086, '<td valign="top">The light is great! I love the 3 distinct areas(the wrinkled plastic, the dreamy window and the dusty round stage for the bottle.) The plant is an added bonus.  I wish the top of the bottle didn''t match up with wood exactly, but other than that it''s perfect.</td>', 'The light is great! I love the 3 distinct areas(the wrinkled plastic, the dreamy window and the dusty round stage for the bottle.) The plant is an added bonus.  I wish the top of the bottle didn''t match up with wood exactly, but other than that it''s perfect.', '2011-08-14 08:28:51.000000', NULL, 1),
(6503894, 965966, 8637, '<td valign="top">Certainly meets the challenge and good angle and composition.  Might have used some lens correction...left side appears a bit skewed.</td>', 'Certainly meets the challenge and good angle and composition.  Might have used some lens correction...left side appears a bit skewed.', '2011-08-14 11:56:29.000000', NULL, 1),
